#include <bits/stdc++.h>
using namespace std;

vector<double> fftTransform(vector<double>& a, bool invert) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j >= bit; bit >>= 1)
            j -= bit;
        j += bit;
        if (i < j)
            swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        double angle = 2 * M_PI / len * (invert ? -1 : 1);
        double wlenCos = cos(angle);
        double wlenSin = sin(angle);
        for (int i = 0; i < n; i += len) {
            double wRe = 1;
            double wIm = 0;
            for (int j = 0; j < len / 2; j++) {
                int u = i + j;
                int v = i + j + len / 2;
                double uVal = a[u];
                double vVal = a[v] * wRe - a[v] * wIm;
                a[u] = uVal + vVal;
                a[v] = uVal - vVal;
                double nextWRe = wRe * wlenCos - wIm * wlenSin;
                double nextWIm = wRe * wlenSin + wIm * wlenCos;
                wRe = nextWRe;
                wIm = nextWIm;
            }
        }
    }
    if (invert) {
        for (int i = 0; i < n; i++) {
            a[i] /= n;
        }
    }
    return a;
}

vector<int> multiplyModulo(const vector<int>& a, const vector<int>& b, int m) {
    int size = 1;
    while (size < (int)a.size() + (int)b.size() - 1) size <<= 1;
    vector<double> A(size, 0), B(size, 0);
    for (size_t i = 0; i < a.size(); i++) {
        int val = ((a[i] % m) + m) % m;
        A[i] = val & 0x7FFF;
    }
    for (size_t i = 0; i < b.size(); i++) {
        int val = ((b[i] % m) + m) % m;
        B[i] = val & 0x7FFF;
    }
    fftTransform(A, false);
    fftTransform(B, false);
    for (int i = 0; i < size; i++) {
        A[i] = A[i] * B[i];
    }
    fftTransform(A, true);
    vector<int> res(a.size() + b.size() - 1);
    for (size_t i = 0; i < res.size(); i++) {
        res[i] = (int)round(A[i]) % m;
    }
    return res;
}

